    m=dict(name=name,slug=slug,tier=tier,rune=rune,reason=reason,l1=l1,l25=early,l6=l6,threats=threat,window=early,errors=threat,trade=trade,side=side,support=support,
        role='adc',lane=tier,late={'Vayne':'E','Xayah':'E','Zeri':'E','Ezreal':'D','Caitlyn':'D','Nilah':'D','Smolder':'D','Yunara':'D'}.get(name,'C'),
        runeReason=('Conqueror als Basis für mehrere Kontaktphasen oder lange Nahkämpfe. '+reason+' Kontrolle/Heilung deines Supports muss das längere Fight-Pattern ermöglichen.' if long else 'PTA nur bei gesicherter kurzer Auto-Serie nach Supportkontakt. '+reason+' Ohne drei Autos auf dasselbe Ziel ist diese Rune kein Argument für einen erzwungenen Engage.'),
        start='Doran’s Shield + Health Potion; Doran’s Blade nur bei realistisch gewinnbarem frühem 2v2 und ausreichendem Schutz vor Poke.',
        sums='Flash + Ghost',
        boots=('Frühe Boots zum Ausweichen; Mercury’s Treads bei relevantem Magieschaden und reduzierbarem CC. Nicht wegen des gegnerischen Rollennamens Steelcaps kaufen.' if ap else 'Frühe Boots für Zugang. Plated Steelcaps bei dominantem gegnerischem Auto-Druck; gegen magischen Support-Poke und gemischten Schaden beide Gegner berücksichtigen.'),
        wave='Wave eher auf eigener Seite halten und vor Crash sicher ausdünnen. '+('Sein/ihr Waveclear kann den Freeze brechen: keine halbe HP-Leiste für das Halten ausgeben. ' if ap or name in ['Sivir','Caitlyn','Tristana'] else 'Mit Supportkontrolle nach gewonnenem Trade slowpushen und vollständig crashen. ')+'Tiamat-Cleave erschwert den Freeze. Cheater Recall nur bei gemeinsam gesichertem Push; bei verlorenem Push nicht erzwingen.',
        items=('Ravenous Hydra für Waveclear/Sustain; bei AP-Poke eine frühe MR-Komponente vorziehen. Danach Maw gegen AP-Burst oder Spirit Visage bei anhaltendem AP-Schaden und relevantem Heil-/Schildwert.' if ap else 'Ravenous Hydra als Sustain-/Waveclear-Basis. Tiamat → Steelcaps → Hydra passt nur, wenn Auto-Schaden die Lane bestimmt. Danach Death’s Dance gegen physischen Druck; offensive Crit-Abzweigung nur bei bereits gesicherter Auto-Zeit.'),
        situ=('Anti-Heal gegen entscheidende Heilung, insbesondere im langen R-Fight. ' if name=='Swain' else '')+'Serpent’s Fang nur wenn wiederholte gegnerische Schilde deinen Finish verhindern. Gegen Crit Randuin’s erwägen, gegen AP-Burst Maw. Sterak’s als alternative Burstabsicherung; nicht mit Maw als doppelte Lifeline einplanen. Crit-Ausbau verlangt Zugriff und Überlebenszeit, kein automatisches Full-Crit ab Hydra.',
        override=('Comp Override: PTA möglich, wenn dein Support den Carry nach dessen Defensivfenster lange genug fixiert und schnelle Picks das Spiel entscheiden.' if long else 'Comp Override: Conqueror, wenn dein erreichbares Ziel meist die Frontline ist oder Schilde/Heilung mehrere Kontaktphasen erzwingen.')+' Flash + Ignite nur bei gesichertem Engage und kurzem Killfenster statt Chase; der Verzicht auf Ghost ist eine bewusste Zugangsentscheidung.',
        plan=early+' '+l6+' '+('Längere Kontakte planen und gegnerische Defensivfenster nicht mit allen Ressourcen beantworten.' if long else 'Supportkontakt für eine kurze Auto-Serie nutzen; ohne Folgekontakt keine Summoners erzwingen.'),
        revision='Neu: unabhängige Olaf-ADC-Analyse, keine Übernahme der Toplane-Wertung.',
        note='Patch 26.18 · geprüft 18.09.2026. Qualitative Kit-Einschätzung für Summoner’s Rift.',
        uncertainty='Vorläufig; keine belastbare Olaf-ADC-Paarungsstatistik. Supportduo, Wave, Level und Zugriff können das Ergebnis stärker verschieben als der Carry allein. Späte-Side-Tier nur grobe isolierte Einordnung bei vergleichbarem Stand.',
        stats=dict(opponentWR=None,n=None,opponentGD=None,rawWR=None,ln=None,delta2=None),
        statsNote='Keine ausreichend belastbare Olaf-ADC-Paarungsstatistik verifiziert. Deshalb keine numerische Winrate und keine Übernahme von Toplane-Statistiken.',
        official=f'https://www.leagueoflegends.com/en-us/champions/{slug}/',
        sources=[['Riot · Olaf','https://www.leagueoflegends.com/en-us/champions/olaf/'],['METAsrc · Botlane-Pool (keine Olaf-Matchupwertung)',poolurl]])
    if ap:m['sources'].append(['LoLalytics · Bot-Rolle (keine Olaf-Paarungsstatistik)',f'https://lolalytics.com/lol/{slug}/build/?lane=bottom'])
    if name=='Seraphine':m['note']+=' E-Abklingzeit in 26.18 auf allen Rängen 11 Sekunden; Haste verkürzt das tatsächliche Fenster.'
    if name=='Zeri':m['note']+=' W-AD-Skalierung in 26.18 reduziert; E-Wandflucht bleibt der zentrale Zugriffsfaktor.'
