data=dict(champion='Olaf',role='adc',patch='26.18',checked='18.09.2026',statsPatch='Keine belastbaren Olaf-ADC-Paarungsdaten',method=method,matchups=sorted(rows,key=lambda x:x['name']))
(root/'olaf-adc.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
out=root/'downloads/adc';out.mkdir(parents=True,exist_ok=True)
for m in rows:(out/f"Olaf_ADC_vs_{m['slug']}.json").write_text(json.dumps(dict(patch=data['patch'],checked=data['checked'],**m),ensure_ascii=False,indent=2),encoding='utf-8')
